/**
 * Go rules engine.
 *
 * A TypeScript port of the rules from the original Python coursework engine
 * (branch `original`), rewritten around a flat, padded array so the
 * bot can simulate thousands of games per second. `engine.test.ts` replays
 * games generated by the original Python engine to prove both agree.
 *
 * Rules (same as the original):
 *  - captures, suicide is illegal
 *  - ko: a move may not recreate the position from before the opponent's last move
 *  - area scoring: stones on the board + empty regions bordered by a single colour
 *  - two consecutive passes end play; the players then mark dead stones,
 *    which are removed before counting (see scoreWithDead)
 */

export const EMPTY = 0;
export const BLACK = 1;
export const WHITE = 2;
export const EDGE = 3;
export const PASS = -1;

export type Stone = typeof BLACK | typeof WHITE;
export type BoardSize = 9 | 13 | 19;

export const opponent = (c: Stone): Stone => (c === BLACK ? WHITE : BLACK);

// Shared scratch space for flood fills. Everything runs on one thread
// (the UI thread or the bot's worker), and no fill is re-entrant.
const MAX_CELLS = 21 * 21;
const stoneMark = new Uint32Array(MAX_CELLS);
const libMark = new Uint32Array(MAX_CELLS);
const stack = new Int32Array(MAX_CELLS);
const groupBuf = new Int32Array(MAX_CELLS);
let gen = 0;

function nextGen(): number {
  gen++;
  if (gen === 0xffffffff) {
    stoneMark.fill(0);
    libMark.fill(0);
    gen = 1;
  }
  return gen;
}

export class Board {
  readonly size: number;
  /** Padded row width: one EDGE cell on each side. */
  readonly W: number;
  readonly dirs: readonly [number, number, number, number];
  readonly diags: readonly [number, number, number, number];
  cells: Uint8Array;
  toPlay: Stone = BLACK;
  /** Point the side to move may not play because of ko, or -1. */
  koPoint = -1;
  /** Consecutive passes; 2 ends the game. */
  passes = 0;
  lastMove = PASS;
  /** Stones captured by each colour (index by Stone). */
  captures: [number, number, number] = [0, 0, 0];
  moveNumber = 0;

  constructor(size: number) {
    this.size = size;
    this.W = size + 2;
    this.dirs = [1, -1, this.W, -this.W];
    this.diags = [this.W + 1, this.W - 1, -this.W + 1, -this.W - 1];
    this.cells = new Uint8Array(this.W * this.W).fill(EDGE);
    for (let y = 0; y < size; y++)
      for (let x = 0; x < size; x++) this.cells[this.idx(x, y)] = EMPTY;
  }

  clone(): Board {
    const b = Object.create(Board.prototype) as Board;
    Object.assign(b, this);
    b.cells = this.cells.slice();
    b.captures = [...this.captures] as [number, number, number];
    return b;
  }

  /** Plain-data snapshot, e.g. to send to a Web Worker. */
  toState(): BoardState {
    const { size, toPlay, koPoint, passes, lastMove, moveNumber } = this;
    return {
      size,
      cells: this.cells.slice(),
      toPlay,
      koPoint,
      passes,
      lastMove,
      moveNumber,
      captures: [...this.captures] as [number, number, number],
    };
  }

  static fromState(s: BoardState): Board {
    const b = new Board(s.size);
    b.cells = s.cells.slice();
    b.toPlay = s.toPlay;
    b.koPoint = s.koPoint;
    b.passes = s.passes;
    b.lastMove = s.lastMove;
    b.moveNumber = s.moveNumber;
    b.captures = [...s.captures] as [number, number, number];
    return b;
  }

  /** x = column (0 = A), y = row (0 = row 1, at the bottom). */
  idx(x: number, y: number): number {
    return (y + 1) * this.W + (x + 1);
  }

  xy(p: number): [number, number] {
    return [(p % this.W) - 1, Math.floor(p / this.W) - 1];
  }

  /** All on-board points in reading order (row 1 first, A to the right). */
  points(): number[] {
    const out: number[] = [];
    for (let y = 0; y < this.size; y++)
      for (let x = 0; x < this.size; x++) out.push(this.idx(x, y));
    return out;
  }

  /** Counts the liberties of the group at p, stopping early once `limit` is reached. */
  liberties(p: number, limit = Infinity): number {
    const color = this.cells[p];
    const g = nextGen();
    const cells = this.cells;
    const dirs = this.dirs;
    let sp = 0;
    let libs = 0;
    stack[sp++] = p;
    stoneMark[p] = g;
    while (sp > 0) {
      const q = stack[--sp];
      for (let i = 0; i < 4; i++) {
        const r = q + dirs[i];
        const c = cells[r];
        if (c === EMPTY) {
          if (libMark[r] !== g) {
            libMark[r] = g;
            if (++libs >= limit) return libs;
          }
        } else if (c === color && stoneMark[r] !== g) {
          stoneMark[r] = g;
          stack[sp++] = r;
        }
      }
    }
    return libs;
  }

  /** Some liberty of the group at p (useful when it has exactly one), or -1. */
  findLiberty(p: number): number {
    const color = this.cells[p];
    const g = nextGen();
    let sp = 0;
    stack[sp++] = p;
    stoneMark[p] = g;
    while (sp > 0) {
      const q = stack[--sp];
      for (let i = 0; i < 4; i++) {
        const r = q + this.dirs[i];
        const c = this.cells[r];
        if (c === EMPTY) return r;
        if (c === color && stoneMark[r] !== g) {
          stoneMark[r] = g;
          stack[sp++] = r;
        }
      }
    }
    return -1;
  }

  /** The stones of the group at p, written into the shared buffer. Returns the count. */
  private collectGroup(p: number): number {
    const color = this.cells[p];
    const g = nextGen();
    let sp = 0;
    let n = 0;
    stack[sp++] = p;
    stoneMark[p] = g;
    while (sp > 0) {
      const q = stack[--sp];
      groupBuf[n++] = q;
      for (let i = 0; i < 4; i++) {
        const r = q + this.dirs[i];
        if (this.cells[r] === color && stoneMark[r] !== g) {
          stoneMark[r] = g;
          stack[sp++] = r;
        }
      }
    }
    return n;
  }

  /** The stones of the group at p, as a fresh array. */
  group(p: number): number[] {
    const n = this.collectGroup(p);
    return Array.from(groupBuf.subarray(0, n));
  }

  isLegal(p: number, color: Stone = this.toPlay): boolean {
    if (p === PASS) return true;
    if (this.cells[p] !== EMPTY) return false;
    if (p === this.koPoint && color === this.toPlay) return false;
    const opp = opponent(color);
    // Cheap check first: an empty neighbour is always a liberty.
    for (let i = 0; i < 4; i++) if (this.cells[p + this.dirs[i]] === EMPTY) return true;
    for (let i = 0; i < 4; i++) {
      const q = p + this.dirs[i];
      const c = this.cells[q];
      // A friendly group keeps a liberty other than p.
      if (c === color && this.liberties(q, 2) >= 2) return true;
      // An enemy group whose only liberty is p gets captured.
      if (c === opp && this.liberties(q, 2) === 1) return true;
    }
    return false; // suicide
  }

  /** Plays a move for the side to move. Throws if it is illegal. */
  play(p: number): void {
    if (p === PASS) {
      this.pass();
      return;
    }
    if (!this.isLegal(p)) throw new Error(`Illegal move at ${p}`);
    this.playUnchecked(p);
  }

  /** Plays a move already known to be legal (hot path for the bot). */
  playUnchecked(p: number): void {
    const color = this.toPlay;
    const opp = opponent(color);
    const cells = this.cells;
    cells[p] = color;

    let captured = 0;
    let capturedAt = -1;
    for (let i = 0; i < 4; i++) {
      const q = p + this.dirs[i];
      if (cells[q] === opp && this.liberties(q, 1) === 0) {
        const n = this.collectGroup(q);
        for (let k = 0; k < n; k++) cells[groupBuf[k]] = EMPTY;
        captured += n;
        capturedAt = q;
      }
    }

    // Ko: a lone stone that captured exactly one stone and now has a single
    // liberty (the captured point) could be retaken immediately, recreating
    // the previous position. Forbid that recapture for one move.
    this.koPoint = -1;
    if (captured === 1) {
      let lone = true;
      for (let i = 0; i < 4; i++) if (cells[p + this.dirs[i]] === color) lone = false;
      if (lone && this.liberties(p, 2) === 1) this.koPoint = capturedAt;
    }

    this.captures[color] += captured;
    this.toPlay = opp;
    this.passes = 0;
    this.lastMove = p;
    this.moveNumber++;
  }

  pass(): void {
    this.koPoint = -1;
    this.passes++;
    this.toPlay = opponent(this.toPlay);
    this.lastMove = PASS;
    this.moveNumber++;
  }

  get isOver(): boolean {
    return this.passes >= 2;
  }

  legalMoves(): number[] {
    return this.points().filter((p) => this.isLegal(p));
  }

  /**
   * Area score, like the original `calculate_points`: stones on the board plus
   * empty regions whose borders are all one colour. Komi is not included.
   */
  score(): { black: number; white: number; territory: Uint8Array } {
    const territory = new Uint8Array(this.cells.length);
    let black = 0;
    let white = 0;
    const seen = new Uint8Array(this.cells.length);
    for (const p of this.points()) {
      const c = this.cells[p];
      if (c === BLACK) black++;
      else if (c === WHITE) white++;
      else if (!seen[p]) {
        // Flood the empty region and note which colours border it.
        const region: number[] = [];
        let borders = 0;
        const todo = [p];
        seen[p] = 1;
        while (todo.length) {
          const q = todo.pop()!;
          region.push(q);
          for (const d of this.dirs) {
            const r = q + d;
            const rc = this.cells[r];
            if (rc === EMPTY && !seen[r]) {
              seen[r] = 1;
              todo.push(r);
            } else if (rc === BLACK || rc === WHITE) borders |= rc;
          }
        }
        if (borders === BLACK || borders === WHITE) {
          if (borders === BLACK) black += region.length;
          else white += region.length;
          for (const q of region) territory[q] = borders;
        }
      }
    }
    return { black, white, territory };
  }

  /**
   * Area score once the players have agreed which stones are dead: those are
   * taken off the board first, so their points (and any empty region they
   * were the only thing spoiling) count for the side that surrounds them.
   */
  scoreWithDead(dead: Iterable<number>): { black: number; white: number; territory: Uint8Array } {
    const b = this.clone();
    for (const p of dead) if (b.cells[p] === BLACK || b.cells[p] === WHITE) b.cells[p] = EMPTY;
    return b.score();
  }

  /** Board as a string of '.', 'X' (black), 'O' (white) in reading order. */
  serialize(): string {
    return this.points()
      .map((p) => '.XO'[this.cells[p]])
      .join('');
  }

  /** "D4"-style coordinates (columns skip I, as is conventional in Go), or "pass". */
  coord(p: number): string {
    if (p === PASS) return 'pass';
    const [x, y] = this.xy(p);
    return COLUMNS[x] + (y + 1);
  }

  /** Parses "D4" or "pass"; returns null for anything that isn't a point on this board. */
  parseCoord(s: string): number | null {
    if (s === 'pass') return PASS;
    const m = /^([A-HJ-T])([1-9][0-9]?)$/.exec(s);
    if (!m) return null;
    const x = COLUMNS.indexOf(m[1]);
    const y = Number(m[2]) - 1;
    if (x >= this.size || y >= this.size) return null;
    return this.idx(x, y);
  }

  /** Like parseCoord, but throws on invalid input (for tests and trusted data). */
  point(s: string): number {
    const p = this.parseCoord(s);
    if (p === null) throw new Error(`Not a point on a ${this.size}×${this.size} board: ${s}`);
    return p;
  }
}

/** Column letters; I is skipped to avoid confusion with J and 1. */
export const COLUMNS = 'ABCDEFGHJKLMNOPQRST';

export interface BoardState {
  size: number;
  cells: Uint8Array;
  toPlay: Stone;
  koPoint: number;
  passes: number;
  lastMove: number;
  moveNumber: number;
  captures: [number, number, number];
}
